"    // Determine the correct printer to use based on the order type
    let printerToUse = posSettings.printerName;
    const orderTypeNormalized = String(order.order_type || '').toUpperCase();

    if (isPreOrder) {
      printerToUse = posSettings.preOrderPrinter || posSettings.printerName;
    } else if (orderTypeNormalized === 'DINE_IN') {
      printerToUse = posSettings.dineInPrinter || posSettings.printerName;
    } else if (orderTypeNormalized === 'PICKUP') {
      printerToUse = posSettings.pickupPrinter || posSettings.printerName;
    } else if (orderTypeNormalized === 'DELIVERY') {
      printerToUse = posSettings.deliveryPrinter || posSettings.printerName;
    } else if (orderTypeNormalized === 'QUICK') {
      printerToUse = posSettings.quickBillPrinter || posSettings.printerName;
    }

    // Determine default title
    const defaultTitle = isBookingReceipt 
      ? 'PRE-ORDER BOOKING RECEIPT' 
      : isSettlement 
        ? 'PRE-ORDER INVOICE (SETTLED)' 
        : 'RETAIL INVOICE';

    // Prepare print tasks
    const printTasks = [];
    if (isPreOrder) {
      if (posSettings.printCustomerCopy !== false) {
        printTasks.push({
          title: isBookingReceipt ? 'PRE-ORDER BOOKING RECEIPT (CUSTOMER COPY)' : 'PRE-ORDER INVOICE (CUSTOMER COPY)',
          printer: printerToUse
        });
      }
      if (posSettings.printRestaurantCopy !== false) {
        printTasks.push({
          title: isBookingReceipt ? 'PRE-ORDER BOOKING RECEIPT (RESTAURANT COPY)' : 'PRE-ORDER INVOICE (RESTAURANT COPY)',
          printer: printerToUse
        });
      }
      if (printTasks.length === 0) {
        printTasks.push({
          title: defaultTitle,
          printer: printerToUse
        });
      }
    } else {
      printTasks.push({
        title: defaultTitle,
        printer: printerToUse
      });
